#include <bits/stdc++.h>
using namespace std;
const int MAXN=510;
typedef pair<int,int> Pair;
#define pair_make make_pair
#define first_elem first
#define second_elem second

int N, M, MOD, C[MAXN][MAXN];
Pair DP[MAXN][MAXN];

int sumRange(int l, int r) {
    return (l + r) * (r - l + 1) / 2;
}

int addMod(int a, int b) {
    int res=a+b;
    if(res>=MOD) res-=MOD;
    return res;
}

Pair operator+(const Pair &a, const Pair &b) {
    return pair_make(addMod(a.first_elem, b.first_elem), addMod(a.second_elem, b.second_elem));
}

Pair operator*(const Pair &a, const Pair &b) {
    long long fi_part=1LL*a.first_elem*b.first_elem%MOD;
    long long se_part=(1LL*a.first_elem*b.second_elem+1LL*a.second_elem*b.first_elem)%MOD;
    return pair_make((int)fi_part, (int)se_part);
}

int main() {
#ifdef LOCAL
    freopen("a.in","r",stdin);
    freopen("a.out","w",stdout);
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin>>N>>M>>MOD;
    for(int i=0;i<MAXN;i++) {
        C[i][0]=1;
        for(int j=1;j<=i;j++) C[i][j]=addMod(C[i-1][j], C[i-1][j-1]);
    }
    for(int i=0;i<=N;i++) {
        DP[i][0]=pair_make(1,0);
        for(int j=1;j<=i && j<=M;j++) {
            if(i!=j) {
                for(int k=1;k<=i;k++)
                    DP[i][j]=DP[i][j]+DP[k-1][k-1]*DP[i-k][j-k+1]*pair_make(C[j][k-1],0);
            } else {
                for(int k=1;k<=i;k++) {
                    auto t1=DP[k-1][k-1];
                    auto t2=DP[i-k][i-k];
                    auto comb=pair_make(C[i-1][k-1],0);
                    int fct= i+1 - sumRange(1,k) + sumRange(k+1,i) - k*(i-k);
                    auto fct_pair=pair_make(fct,0);
                    DP[i][j]=DP[i][j]+t1*t2*comb*fct_pair;
                }
            }
        }
    }
    cout<<DP[N][M].second_elem;
    return 0;
}
